static int ars(int v,int n){if(v>=0)return v>>n;return -(((-v)+(1<<n)-1)/(1<<n));}
static void deq_ref(const int* q,int* o,int n,int dq,int mq,bool nu){for(int i=0;i<n;++i){long v=long(q[i])*dq;if(nu&&q[i])v+=q[i]>0?mq:-mq;o[i]=int(v);}}
static void inv8row(const int*s,int*d){int t1=12*(s[0]+s[4])+4,t2=12*(s[0]-s[4])+4,t3=16*s[2]+6*s[6],t4=6*s[2]-16*s[6],t5=t1+t3,t6=t2+t4,t7=t2-t4,t8=t1-t3;t1=16*s[1]+15*s[3]+9*s[5]+4*s[7];t2=15*s[1]-4*s[3]-16*s[5]-9*s[7];t3=9*s[1]-16*s[3]+4*s[5]+15*s[7];t4=4*s[1]-9*s[3]+15*s[5]-16*s[7];d[0]=ars(t5+t1,3);d[1]=ars(t6+t2,3);d[2]=ars(t7+t3,3);d[3]=ars(t8+t4,3);d[4]=ars(t8-t4,3);d[5]=ars(t7-t3,3);d[6]=ars(t6-t2,3);d[7]=ars(t5-t1,3);}
static void inv4row(const int*s,int*d){int t1=17*(s[0]+s[2])+4,t2=17*(s[0]-s[2])+4,t3=22*s[1]+10*s[3],t4=22*s[3]-10*s[1];d[0]=ars(t1+t3,3);d[1]=ars(t2-t4,3);d[2]=ars(t2+t4,3);d[3]=ars(t1-t3,3);}
static void invrect_ref(int*a,int type){std::array<int,64> t{};if(type==1){for(int y=0;y<4;++y)inv8row(a+y*8,t.data()+y*8);for(int x=0;x<8;++x){int A=17*(t[x]+t[16+x])+64,B=17*(t[x]-t[16+x])+64,C=22*t[8+x]+10*t[24+x],D=22*t[24+x]-10*t[8+x];a[x]=ars(A+C,7);a[8+x]=ars(B-D,7);a[16+x]=ars(B+D,7);a[24+x]=ars(A-C,7);}return;}int rows=type==2?8:4;for(int y=0;y<rows;++y)inv4row(a+y*8,t.data()+y*8);if(type==3){for(int x=0;x<4;++x){int A=17*(t[x]+t[16+x])+64,B=17*(t[x]-t[16+x])+64,C=22*t[8+x]+10*t[24+x],D=22*t[24+x]-10*t[8+x];a[x]=ars(A+C,7);a[8+x]=ars(B-D,7);a[16+x]=ars(B+D,7);a[24+x]=ars(A-C,7);}return;}for(int x=0;x<4;++x){const int*s=t.data()+x;int A=12*(s[0]+s[32])+64,B=12*(s[0]-s[32])+64,C=16*s[16]+6*s[48],D=6*s[16]-16*s[48],E=A+C,F=B+D,G=B-D,H=A-C;A=16*s[8]+15*s[24]+9*s[40]+4*s[56];B=15*s[8]-4*s[24]-16*s[40]-9*s[56];C=9*s[8]-16*s[24]+4*s[40]+15*s[56];D=4*s[8]-9*s[24]+15*s[40]-16*s[56];a[x]=ars(E+A,7);a[8+x]=ars(F+B,7);a[16+x]=ars(G+C,7);a[24+x]=ars(H+D,7);a[32+x]=ars(H-D+1,7);a[40+x]=ars(G-C+1,7);a[48+x]=ars(F-B+1,7);a[56+x]=ars(E-A+1,7);}}
static int oas3(int v){return v>=0?v>>3:-((-v+7)>>3);} 
static void ov_v_ref(int*e,int s){for(int i=0;i<8;++i){int*a=e+i*s;int A=a[0],B=a[1],C=a[2],D=a[3],d1=A-D,d2=A-D+B-C,r1=(i&1)?3:4,r2=7-r1;a[0]=oas3(8*A-d1+r1);a[1]=oas3(8*B-d2+r2);a[2]=oas3(8*C+d2+r1);a[3]=oas3(8*D+d1+r2);}}
static void ov_h_ref(int*e,int s){for(int i=0;i<8;++i){int A=e[-2*s+i],B=e[-s+i],C=e[i],D=e[s+i],d1=A-D,d2=A-D+B-C,r1=(i&1)?3:4,r2=7-r1;e[-2*s+i]=oas3(8*A-d1+r1);e[-s+i]=oas3(8*B-d2+r2);e[i]=oas3(8*C+d2+r1);e[s+i]=oas3(8*D+d1+r2);}}
static bool lfline(std::vector<uint8_t>&p,int w,int x,int y,int dx,int dy,int pq){auto sm=[&](int k){return int(p[size_t(y+k*dy)*w+x+k*dx]);};int a0=ars(2*(sm(-2)-sm(1))-5*(sm(-1)-sm(0))+4,3),sg=a0<0;a0=std::abs(a0);if(a0>=pq)return false;int a1=std::abs(ars(2*(sm(-4)-sm(-1))-5*(sm(-3)-sm(-2))+4,3)),a2=std::abs(ars(2*(sm(0)-sm(3))-5*(sm(1)-sm(2))+4,3));if(!(a1<a0||a2<a0))return false;int edge=sm(-1)-sm(0),lim=std::abs(edge)>>1;if(!lim)return false;int d=(5*(a0-std::min(a1,a2)))>>3;if(sg!=(edge<0)){d=std::min(d,lim);if(edge<0)d=-d;auto&pp=p[size_t(y-dy)*w+x-dx];auto&qq=p[size_t(y)*w+x];pp=uint8_t(std::clamp(int(pp)-d,0,255));qq=uint8_t(std::clamp(int(qq)+d,0,255));}return true;}
static void lf4_ref(std::vector<uint8_t>&p,int w,int x,int y,bool v,int pq){int adx=v?0:1,ady=v?1:0,cdx=v?1:0,cdy=v?0:1;if(!lfline(p,w,x+2*adx,y+2*ady,cdx,cdy,pq))return;lfline(p,w,x,y,cdx,cdy,pq);lfline(p,w,x+adx,y+ady,cdx,cdy,pq);lfline(p,w,x+3*adx,y+3*ady,cdx,cdy,pq);}
int main(){std::mt19937 r(12345);std::uniform_int_distribution<int> qd(-2047,2047),id(-20000,20000),bd(0,255);for(int z=0;z<200;++z){std::array<int,64>q{},a{},b{};for(int&i:q)i=qd(r);deq_ref(q.data(),a.data(),64,37,19,z&1);simd::dequant_coefficients_x86_64_v1(q.data(),b.data(),64,37,19,z&1);if(a!=b)return 1;for(int type=1;type<=3;++type){for(int&i:a)i=id(r);b=a;invrect_ref(a.data(),type);simd::inverse_transform_rect_x86_64_v1(b.data(),type);if(a!=b)return 2;}}
for(int z=0;z<100;++z){const int w=24,h=24;std::vector<int>a(w*h),b;for(int&i:a)i=id(r);b=a;ov_v_ref(a.data()+8*w+6,w);simd::overlap_vertical8_x86_64_v1(b.data()+8*w+6,w);if(a!=b)return 3;a=b;ov_h_ref(a.data()+8*w+8,w);simd::overlap_horizontal8_x86_64_v1(b.data()+8*w+8,w);if(a!=b)return 4;std::vector<uint8_t>u(w*h),v;for(auto&i:u)i=uint8_t(bd(r));v=u;lf4_ref(u,w,6,8,false,9);simd::loop_filter4_h_x86_64_v1(v.data(),w,6,8,9);if(u!=v)return 5;u=v;lf4_ref(u,w,8,6,true,9);simd::loop_filter4_v_x86_64_v1(v.data(),w,8,6,9);if(u!=v)return 6;}return 0;}
